create or replace view public.location_intelligence_snapshot with (security_invoker=true) as select p.id place_id,p.location_id,p.name,p.category,p.latitude,p.longitude,coalesce(ri.intelligence_score,0) intelligence_score,ri.freshness_label,ri.last_observed_at,coalesce(ri.base_cleanliness_pct,0) cleanliness_pct,coalesce(ri.verification_count,0) verification_count,coalesce(ri.observation_count,0) observation_count,count(dfe.id) filter(where dfe.event_type='search' and dfe.occurred_at>=now()-interval '7 days') searches_7d,count(dfe.id) filter(where dfe.event_type='search' and dfe.occurred_at>=now()-interval '30 days') searches_30d,count(dfe.id) filter(where dfe.event_type='location_view' and dfe.occurred_at>=now()-interval '30 days') views_30d,count(dfe.id) filter(where dfe.event_type='directions_requested' and dfe.occurred_at>=now()-interval '30 days') directions_30d,count(dfe.id) filter(where dfe.event_type='arrival' and dfe.occurred_at>=now()-interval '30 days') arrivals_30d,count(dfe.id) filter(where dfe.event_type='check_in' and dfe.occurred_at>=now()-interval '30 days') checkins_30d,count(dfe.id) filter(where dfe.event_type='review_submitted' and dfe.occurred_at>=now()-interval '30 days') reviews_30d,now() calculated_at from public.places p left join public.restroom_intelligence ri on ri.place_id=p.id left join public.data_feature_events dfe on dfe.location_id=p.location_id where p.is_active=true group by p.id,p.location_id,p.name,p.category,p.latitude,p.longitude,ri.intelligence_score,ri.freshness_label,ri.last_observed_at,ri.base_cleanliness_pct,ri.verification_count,ri.observation_count; create or replace function public.business_location_intelligence(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language plpgsql security definer set search_path to 'public','pg_temp' as $$ begin if auth.uid() is null then raise exception 'Authentication required'; end if; if not public.business_can_manage(p_business_id) and not exists(select 1 from public.business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and bm.role='analyst') then raise exception 'Not authorized for this business'; end if; return coalesce((select jsonb_agg(jsonb_build_object('location_id',x.location_id,'place_id',x.place_id,'name',x.name,'category',x.category,'intelligence_score',x.intelligence_score,'cleanliness_pct',x.cleanliness_pct,'verification_count',x.verification_count,'observation_count',x.observation_count,'searches',x.searches,'views',x.views,'directions',x.directions,'arrivals',x.arrivals,'check_ins',x.check_ins,'reviews',x.reviews,'freshness_label',x.freshness_label) order by x.searches desc,x.check_ins desc,x.name) from (select s.*,coalesce((select count(*) from public.data_feature_events e where e.location_id=s.location_id and e.event_type='search' and e.occurred_at between p_start and p_end),0) searches,coalesce((select count(*) from public.data_feature_events e where e.location_id=s.location_id and e.event_type='location_view' and e.occurred_at between p_start and p_end),0) views,coalesce((select count(*) from public.data_feature_events e where e.location_id=s.location_id and e.event_type='directions_requested' and e.occurred_at between p_start and p_end),0) directions,coalesce((select count(*) from public.data_feature_events e where e.location_id=s.location_id and e.event_type='arrival' and e.occurred_at between p_start and p_end),0) arrivals,coalesce((select count(*) from public.data_feature_events e where e.location_id=s.location_id and e.event_type='check_in' and e.occurred_at between p_start and p_end),0) check_ins,coalesce((select count(*) from public.data_feature_events e where e.location_id=s.location_id and e.event_type='review_submitted' and e.occurred_at between p_start and p_end),0) reviews from public.location_intelligence_snapshot s join public.locations l on l.id=s.location_id where l.business_id=p_business_id) x),'[]'::jsonb); end; $$;
